args.query:
// Get all Argentina pass pairs (bidirectional)
MATCH (j1:Jogador)-[:MEMBRO_DE]->(t:Time {nome: 'Argentina'})
MATCH (j2:Jogador)-[:MEMBRO_DE]->(t)
WHERE j1 <> j2
  AND (
    EXISTS {
      MATCH (j1)-[p:PASSOU_PARA {match_id: 3869685}]->(j2)
    } OR EXISTS {
      MATCH (j2)-[p:PASSOU_PARA {match_id: 3869685}]->(j1)
    }
  )
RETURN j1.nome AS jogador, collect(DISTINCT j2.nome) AS parceiros, count(DISTINCT j2.nome) AS num_parceiros
ORDER BY num_parceiros

// Build undirected pass network for France in extra time
// For each France player, find all their pass neighbors (undirected)
MATCH (j1:Jogador)-[p:PASSOU_PARA]->(j2:Jogador)
WHERE p.match_id = 3869685
  AND p.periodo IN [3, 4]
  AND EXISTS { (j1)-[:MEMBRO_DE]->(:Time {nome: 'France'}) }
  AND EXISTS { (j2)-[:MEMBRO_DE]->(:Time {nome: 'France'}) }
WITH collect({a: j1.nome, b: j2.nome}) AS edges

// Get all unique player pairs (undirected)
UNWIND edges AS e
WITH collect(DISTINCT e.a) + collect(DISTINCT e.b) AS all_players_dup, edges
UNWIND all_players_dup AS p
WITH collect(DISTINCT p) AS players, edges

// For each player, find their neighbors
UNWIND players AS player
WITH player, edges,
     [e IN edges WHERE e.a = player | e.b] +
     [e IN edges WHERE e.b = player | e.a] AS neighbors_dup
WITH player, [n IN collect(DISTINCT neighbors_dup) | n][0] AS nb_raw
// Flatten
RETURN player, nb_raw
ORDER BY size(nb_raw) ASC
